#include "stdafx.h"
#include "LoadingBenchmark.h"
#include "GameFramework.h"
#include "NetworkManager.h"
#include "SceneManager.h"
#include "SoundManager.h"
#include <chrono>
#include <filesystem>
#include <iomanip>
#include <fstream>
#include <stdexcept>
#include <psapi.h>
#pragma comment(lib,"psapi.lib")

namespace { bool active=false; }
bool LoadingBenchmarkActive() { return active; }

int CGameFramework::BenchmarkSceneLoading(const wchar_t* reportPath)
{
    active=true;
    _set_error_mode(_OUT_TO_STDERR);
    _set_abort_behavior(0,_WRITE_ABORT_MSG|_CALL_REPORTFAULT);
    SetErrorMode(SEM_FAILCRITICALERRORS|SEM_NOGPFAULTERRORBOX);
    using Clock=std::chrono::steady_clock;
    struct Result { const char* label; double readyMs,loaderMs; unsigned long long privateBytes; };
    std::vector<Result> results;
    std::ofstream output;
    output.open(std::filesystem::path(reportPath));
    if (!output) return 2;
    auto write=[&](bool ok,const char* phase) {
        output.close();
        output.open(std::filesystem::path(reportPath),std::ios::trunc);
        output << std::setprecision(12) << "{\"ok\":" << (ok?"true":"false") << ",\"phase\":\"" << phase
               << "\",\"offline\":true,\"loadingThread\":true,\"width\":" << FRAME_BUFFER_WIDTH << ",\"height\":" << FRAME_BUFFER_HEIGHT << ",\"segments\":[";
        for (size_t i=0;i<results.size();++i) {
            if (i) output << ',';
            auto& r=results[i]; output << "{\"label\":\"" << r.label << "\",\"readyMs\":" << r.readyMs << ",\"loaderMs\":" << r.loaderMs << ",\"privateBytes\":" << r.privateBytes << '}';
        }
        output << "]}\n"; output.flush();
    };
    try {
        auto net=NetworkManager::GetInstance();
        net->Initialize(""); net->SetId(0);
        net->readySceneInfo->playerJobs={0,1,2,4};
        const int skills[4][4]={{48,53,54,58},{60,65,69,70},{72,79,81,82},{24,27,29,30}};
        for (int player=0;player<4;++player)
            for (int slot=0;slot<4;++slot) net->readySceneInfo->selectSkills[player][slot]=skills[player][slot];
        ModelCustomize appearance{0,1,0,0,1,1,3,1,0,1,0,0,1,1,1,1,0,1,3,2,2,2,2,1,1,1,1,1};
        for (int slot=0;slot<3;++slot) net->m_ArrayInGameClientsCustom[slot]=appearance;
#ifdef LOADING_BENCH_OPTIMIZED
        for (int slot=0;slot<3;++slot) net->StoreIngameAppearance(slot,appearance);
#endif
        for (int slot=0;slot<5;++slot) {
            net->structureInfo[slot].active=false; net->structureInfo[slot].broken=false;
            net->structureInfo[slot].curHp=net->structureInfo[slot].maxHp=100;
        }
        SceneManager::GetInstance()->SetOrder(ORDER::PLAYER1);
        strcpy_s(SceneManager::GetInstance()->m_Name,NAME_SIZE,"DummyLoad");
        const auto instance=GetModuleHandle(nullptr); ghAppInstance=instance;
        RECT rectangle{0,0,FRAME_BUFFER_WIDTH,FRAME_BUFFER_HEIGHT};
        AdjustWindowRect(&rectangle,WS_OVERLAPPEDWINDOW,FALSE);
        auto window=CreateWindowEx(0,L"STATIC",L"WOD loading benchmark",WS_OVERLAPPEDWINDOW,
            0,0,rectangle.right-rectangle.left,rectangle.bottom-rectangle.top,nullptr,nullptr,instance,nullptr);
        if (!window || !OnCreate(instance,window)) throw std::runtime_error("benchmark initialization");
        net->playerScene=SCENEKIND::TITLE;
        for (int frame=0;frame<2;++frame) FrameAdvance();
        WaitForGpuComplete(); write(false,"title_ready");
        auto transition=[&](SCENEKIND scene,const char* label,const wchar_t* bgm,float volume) {
            const auto started=Clock::now();
            net->playerScene=scene;
            ChangeScene(scene);
            const auto loaded=Clock::now();
            if (SceneManager::GetInstance()->m_nCurScene!=scene) throw std::runtime_error("scene mismatch");
            SoundManager::GetInstance()->Play_BGM(bgm,volume);
            FrameAdvance(); WaitForGpuComplete();
            if (FAILED(m_pd3dDevice->GetDeviceRemovedReason())) throw std::runtime_error("GPU device removed");
            PROCESS_MEMORY_COUNTERS_EX memory{}; memory.cb=sizeof(memory);
            GetProcessMemoryInfo(GetCurrentProcess(),reinterpret_cast<PROCESS_MEMORY_COUNTERS*>(&memory),sizeof(memory));
            const auto finished=Clock::now();
            results.push_back({label,std::chrono::duration<double,std::milli>(finished-started).count(),
                std::chrono::duration<double,std::milli>(loaded-started).count(),memory.PrivateUsage});
            write(false,label);
        };
        transition(SCENEKIND::LOBBY,"title_to_lobby",L"LobbyBGM.wav",0.2f);
        transition(SCENEKIND::READY,"lobby_to_ready",L"ReadyBGM.ogg",1.4f);
        transition(SCENEKIND::INGAME,"ready_to_ingame",L"IngameBGM.mp3",0.1f);
        for (int frame=0;frame<10;++frame) FrameAdvance();
        WaitForGpuComplete();
        transition(SCENEKIND::LOBBY,"ingame_to_lobby",L"LobbyBGM.wav",0.2f);
        write(true,"complete"); return 0;
    } catch (const std::exception& error) {
        std::cerr << "Loading benchmark failed: " << error.what() << '\n';
        write(false,"failed"); return 1;
    }
}
